// Original CSS artwork; no remote images, runtime downloads or paid assets.
export const WALLPAPERS=[
 {id:'lagoon-image',name:'Lagoon sunset',background:'center / cover url(assets/wallpapers/lagoon-image.svg)'},
 {id:'garden-image',name:'Garden shade',background:'center / cover url(assets/wallpapers/garden-image.svg)'},
 {id:'city-image',name:'City lights',background:'center / cover url(assets/wallpapers/city-image.svg)'},
 {id:'lagoon',name:'Lagoon dusk',background:'radial-gradient(ellipse at 10% 90%,#66839e,transparent 49%),radial-gradient(ellipse at 100% 55%,#367b79,transparent 56%),linear-gradient(160deg,#172c53,#28586c 55%,#567b8b)'},
 {id:'palm',name:'Palm shade',background:'repeating-linear-gradient(135deg,transparent 0 35px,#ffffff09 36px 38px),linear-gradient(155deg,#092e29,#265846 60%,#7e7b3d)'},
 {id:'indigo',name:'Indigo weave',background:'repeating-linear-gradient(45deg,#ffffff06 0 2px,transparent 2px 18px),repeating-linear-gradient(-45deg,#ffffff06 0 2px,transparent 2px 18px),linear-gradient(145deg,#171e45,#39376b)'},
 {id:'terracotta',name:'Warm earth',background:'radial-gradient(circle at 85% 15%,#e2a76d 0 13%,transparent 13.5%),linear-gradient(160deg,#4a2834,#8c4b3d 65%,#bc8157)'},
 {id:'coast',name:'Coastal night',background:'radial-gradient(ellipse at 80% 100%,#376784 0 30%,transparent 31%),radial-gradient(ellipse at 10% 120%,#264d68 0 60%,transparent 61%),linear-gradient(#0a1838,#1a4260)'},
 {id:'plum',name:'Plum glow',background:'radial-gradient(ellipse at 90% 80%,#995c69,transparent 65%),linear-gradient(145deg,#241b37,#523350)'}
];
export const wallpaper=id=>WALLPAPERS.find(w=>w.id===id)||WALLPAPERS[0];
export const validPhoneAppearance=p=>p===undefined||!!p&&WALLPAPERS.some(w=>w.id===p.wallpaper);
export function createWallpaperApp({root,state,save,toast}){
 let preview=null;
 function gallery(){preview=null;root.innerHTML='<p>Choose a free wallpaper for your in-game Phone.</p><div class="wallpaper-gallery">'+WALLPAPERS.map(w=>'<button id="wallpaper-'+w.id+'" class="wallpaper-tile" aria-label="Preview '+w.name+'"><span class="wallpaper-thumb" style="background:'+w.background+'"></span><strong>'+w.name+'</strong><small>'+(state.phoneAppearance.wallpaper===w.id?'Applied':'Free')+'</small></button>').join('')+'</div>';for(const w of WALLPAPERS)root.querySelector('#wallpaper-'+w.id).onclick=()=>show(w);}
 function show(w){preview=w;root.innerHTML='<button id="wallpaper-back" class="secondary">‹ Gallery</button><h3 class="wallpaper-title">'+w.name+'</h3><div class="wallpaper-preview" style="background:'+w.background+'"><strong class="wallpaper-label">Phone</strong><div class="wallpaper-sample-icons" aria-label="Readability preview"><span>Jobs</span><span>Food</span><span>Settings</span></div><span class="wallpaper-label">Your city. Your day.</span></div><p>In-game Phone only · Free</p><button id="wallpaper-apply" class="primary">'+(state.phoneAppearance.wallpaper===w.id?'Applied':'Apply wallpaper')+'</button><p id="wallpaper-status" role="status"></p>';root.querySelector('#wallpaper-back').onclick=gallery;const apply=root.querySelector('#wallpaper-apply');apply.disabled=state.phoneAppearance.wallpaper===w.id;apply.onclick=()=>{if(!preview)return;state.phoneAppearance.wallpaper=preview.id;save();apply.textContent='Applied';apply.disabled=true;root.querySelector('#wallpaper-status').textContent='Saved. Return Home to see your wallpaper.';toast('Phone wallpaper saved.');};}
 const originalGallery=gallery;gallery=()=>{originalGallery();const theme=document.createElement('section');theme.innerHTML='<h3>Phone theme</h3><div id="theme-preview" class="card">Readable menus · Wallet ₦15,000</div><button id="theme-night">Midnight</button><button id="theme-forest">Forest</button><button id="theme-plum">Plum</button><button id="theme-apply">Apply theme</button>';root.appendChild(theme);let selected=state.phoneAppearance.theme||'night';const colours={night:'#172a36',forest:'#193c32',plum:'#392b46'};const preview=()=>{theme.querySelector('#theme-preview').style.background=colours[selected];};for(const id of Object.keys(colours))theme.querySelector('#theme-'+id).onclick=()=>{selected=id;preview();};theme.querySelector('#theme-apply').onclick=()=>{state.phoneAppearance.theme=selected;document.getElementById('sheet').dataset.phoneTheme=selected;save();toast('Phone theme saved.');};preview();};gallery();return {tick(){},dispose(){preview=null;}};
}
